INSERT INTO public.hit_report_modules (id, category, title, content) VALUES
('TRK-consumer_insight-H', 'track_competency', '소비자 인사이트 — 강점으로 보여 주기', '조사 자료에서 광고에 쓸 통찰을 뽑아내는 힘이 강점입니다. 포트폴리오에 "데이터 → 인사이트 한 문장 → 아이디어"로 이어지는 과정을 보여 주세요.'),
('TRK-consumer_insight-M', 'track_competency', '소비자 인사이트 — 다음에 더할 것', '인사이트를 찾는 감각은 있습니다. 소비자 인터뷰나 리뷰 분석을 직접 해 보고, 찾은 인사이트를 한 문장으로 쓰는 연습을 더해 보세요.'),
('TRK-consumer_insight-L', 'track_competency', '소비자 인사이트 — 첫걸음', '좋아하는 광고 다섯 편을 골라 "이 광고는 소비자의 어떤 마음을 건드렸나"를 한 줄씩 적어 보는 것부터 시작하세요.'),
('TRK-creative_concept-H', 'track_competency', '크리에이티브 콘셉트 — 강점으로 보여 주기', '메시지를 하나로 좁히고 아이디어로 넓히는 힘이 뚜렷합니다. 공모전·과제에서 낸 콘셉트를 보드 한 장으로 정리해 두면 강력한 증거가 됩니다.'),
('TRK-creative_concept-M', 'track_competency', '크리에이티브 콘셉트 — 다음에 더할 것', '아이디어는 낼 수 있습니다. 하나의 브리프로 방향이 다른 콘셉트 세 개를 만들어 보는 연습이 폭을 넓혀 줍니다.'),
('TRK-creative_concept-L', 'track_competency', '크리에이티브 콘셉트 — 첫걸음', '수상작 캠페인을 보고 "핵심 메시지 한 줄"을 거꾸로 추출해 보세요. 콘셉트가 어떻게 만들어지는지 구조가 보이기 시작합니다.'),
('TRK-media_planning-H', 'track_competency', '미디어 플래닝 — 강점으로 보여 주기', '타깃과 예산에 맞게 매체를 짜는 감각이 있습니다. 가상의 예산으로 매체 믹스와 그 근거를 한 장에 정리해 두면 면접에서 바로 쓸 수 있습니다.'),
('TRK-media_planning-M', 'track_competency', '미디어 플래닝 — 다음에 더할 것', '매체별 특징은 압니다. 도달·빈도·CPM 같은 지표로 매체를 비교해 보는 연습을 더하면 설득력이 생깁니다.'),
('TRK-media_planning-L', 'track_competency', '미디어 플래닝 — 첫걸음', '내가 하루 동안 접한 광고를 매체별로 적어 보세요. 타깃이 어디서 광고를 만나는지 감이 잡히기 시작합니다.'),
('TRK-copy_story-H', 'track_competency', '카피·스토리 — 강점으로 보여 주기', '짧은 말과 이야기로 가치를 전하는 힘이 강점입니다. 내가 쓴 카피와 고친 과정을 함께 보여 주면 실력이 분명하게 드러납니다.'),
('TRK-copy_story-M', 'track_competency', '카피·스토리 — 다음에 더할 것', '카피를 쓸 수 있습니다. 같은 메시지를 15초 영상·배너·SNS 세 가지 길이로 바꿔 써 보면 한 단계 올라갑니다.'),
('TRK-copy_story-L', 'track_competency', '카피·스토리 — 첫걸음', '매일 광고 카피 하나를 필사하고 내 말로 다시 써 보세요. 짧은 문장에 힘을 싣는 감각이 길러집니다.'),
('TRK-campaign_execution-H', 'track_competency', '캠페인 실행 — 강점으로 보여 주기', '일정·제작·협업을 관리해 캠페인을 완성하는 힘이 있습니다. 내가 맡은 캠페인의 일정표와 문제 해결 사례를 정리해 두면 실무 역량의 증거가 됩니다.'),
('TRK-campaign_execution-M', 'track_competency', '캠페인 실행 — 다음에 더할 것', '실행을 따라갈 수 있습니다. 작은 캠페인 하나를 처음부터 끝까지 직접 맡아 일정을 역산해 관리해 보세요.'),
('TRK-campaign_execution-L', 'track_competency', '캠페인 실행 — 첫걸음', '동아리·학회 행사 하나의 준비 과정을 일정표로 만들어 보세요. 실행의 기본은 일정 관리에서 시작합니다.'),
('TRK-ad_measurement-H', 'track_competency', '광고 효과 측정 — 강점으로 보여 주기', '목표 지표를 정하고 결과를 분석하는 힘이 강점입니다. 캠페인 결과 보고서 한 장을 포트폴리오에 넣으면 기획과 성과를 함께 보여 줄 수 있습니다.'),
('TRK-ad_measurement-M', 'track_competency', '광고 효과 측정 — 다음에 더할 것', '지표의 뜻은 압니다. 캠페인 목표에 맞는 KPI를 먼저 정하고, 끝난 뒤 원인을 나눠 분석하는 연습을 더해 보세요.'),
('TRK-ad_measurement-L', 'track_competency', '광고 효과 측정 — 첫걸음', '도달·인지도·전환 같은 기본 지표의 뜻을 정리하고, 공개된 캠페인 사례 보고서 하나를 읽어 보는 것부터 시작하세요.'),
('TRK-brand_strategy-H', 'track_competency', '브랜드 전략 — 강점으로 보여 주기', '브랜드의 약속과 포지셔닝을 세우는 힘이 뚜렷합니다. 좋아하는 브랜드 하나를 골라 포지셔닝을 다시 설계한 제안서를 만들어 두면 좋은 증거가 됩니다.'),
('TRK-brand_strategy-M', 'track_competency', '브랜드 전략 — 다음에 더할 것', '전략의 틀은 이해합니다. 경쟁 브랜드와의 포지셔닝 맵을 직접 그려 보며 근거를 찾는 연습을 더해 보세요.'),
('TRK-brand_strategy-L', 'track_competency', '브랜드 전략 — 첫걸음', '관심 있는 브랜드 세 곳의 "누구에게 어떤 가치를 약속하는가"를 한 문장씩 적어 보는 것부터 시작하세요.'),
('TRK-brand_identity-H', 'track_competency', '브랜드 아이덴티티 — 강점으로 보여 주기', '이름·시각·말투를 브랜드답게 다듬는 감각이 강점입니다. 아이덴티티 개선 제안을 전후 비교로 보여 주면 설득력이 큽니다.'),
('TRK-brand_identity-M', 'track_competency', '브랜드 아이덴티티 — 다음에 더할 것', '아이덴티티 요소를 볼 줄 압니다. 브랜드 가이드라인 하나를 직접 만들어 보는 연습이 실무 감각을 키웁니다.'),
('TRK-brand_identity-L', 'track_competency', '브랜드 아이덴티티 — 첫걸음', '브랜드 로고·컬러·말투가 서로 맞는 사례와 어긋나는 사례를 하나씩 찾아 비교해 보세요.'),
('TRK-brand_experience-H', 'track_competency', '브랜드 경험 — 강점으로 보여 주기', '고객 접점의 경험을 설계하는 힘이 있습니다. 고객 여정 지도와 개선안을 한 장으로 정리하면 실력이 분명히 보입니다.'),
('TRK-brand_experience-M', 'track_competency', '브랜드 경험 — 다음에 더할 것', '접점을 점검할 수 있습니다. 매장·앱·고객센터를 직접 써 보고 경험이 끊기는 지점을 기록하는 연습을 더해 보세요.'),
('TRK-brand_experience-L', 'track_competency', '브랜드 경험 — 첫걸음', '최근 이용한 브랜드 하나의 구매 과정을 단계별로 적고, 좋았던 점과 불편했던 점을 표시해 보세요.'),
('TRK-consumer_research-H', 'track_competency', '소비자 조사 — 강점으로 보여 주기', '조사를 설계하고 결론을 끌어내는 힘이 강점입니다. 직접 설계한 설문·인터뷰와 그 결론을 정리해 두면 브랜드 직무에서 큰 강점이 됩니다.'),
('TRK-consumer_research-M', 'track_competency', '소비자 조사 — 다음에 더할 것', '조사 결과를 읽을 수 있습니다. 작은 설문 하나를 직접 설계해 보고 질문의 편향을 점검하는 연습을 더해 보세요.'),
('TRK-consumer_research-L', 'track_competency', '소비자 조사 — 첫걸음', '공개된 소비자 트렌드 리포트 하나를 읽고, 우리 브랜드라면 무엇을 바꿀지 세 줄로 정리해 보세요.'),
('TRK-brand_portfolio-H', 'track_competency', '브랜드 포트폴리오 — 강점으로 보여 주기', '여러 브랜드와 라인의 관계를 정리하는 시야가 있습니다. 한 기업의 브랜드 구조를 분석한 자료는 전략 역량의 좋은 증거가 됩니다.'),
('TRK-brand_portfolio-M', 'track_competency', '브랜드 포트폴리오 — 다음에 더할 것', '구조를 이해합니다. 라인 확장과 신규 브랜드 사례를 비교해 성공과 실패 요인을 정리해 보세요.'),
('TRK-brand_portfolio-L', 'track_competency', '브랜드 포트폴리오 — 첫걸음', '관심 기업 하나의 브랜드·제품 라인을 나무 구조로 그려 보는 것부터 시작하세요.'),
('TRK-brand_health-H', 'track_competency', '브랜드 건강도 — 강점으로 보여 주기', '브랜드 지표를 추적하고 성과로 설명하는 힘이 강점입니다. 지표로 브랜드 상태를 진단한 보고서는 경영진 보고 역량을 보여 줍니다.'),
('TRK-brand_health-M', 'track_competency', '브랜드 건강도 — 다음에 더할 것', '지표의 의미는 압니다. 인지도·선호도·추천 의향이 매출과 어떻게 이어지는지 사례로 정리해 보세요.'),
('TRK-brand_health-L', 'track_competency', '브랜드 건강도 — 첫걸음', '브랜드 인지도·선호도·추천 의향이 각각 무엇을 재는지 정리하는 것부터 시작하세요.'),
('TRK-content_strategy-H', 'track_competency', '콘텐츠 전략 — 강점으로 보여 주기', '목적과 타깃에 맞게 콘텐츠를 기획하는 힘이 강점입니다. 직접 짠 콘텐츠 캘린더와 그 결과를 함께 보여 주면 설득력이 큽니다.'),
('TRK-content_strategy-M', 'track_competency', '콘텐츠 전략 — 다음에 더할 것', '기획의 틀은 있습니다. 채널별 역할을 나누고 한 달 캘린더를 직접 짜 보는 연습을 더해 보세요.'),
('TRK-content_strategy-L', 'track_competency', '콘텐츠 전략 — 첫걸음', '팔로우하는 계정 하나를 골라 콘텐츠를 목적(인지·관계·전환)별로 나눠 보는 것부터 시작하세요.'),
('TRK-storytelling-H', 'track_competency', '스토리텔링 — 강점으로 보여 주기', '정보를 이야기로 바꿔 관심을 끄는 힘이 뚜렷합니다. 반응이 좋았던 콘텐츠와 그 구성 의도를 정리해 두세요.'),
('TRK-storytelling-M', 'track_competency', '스토리텔링 — 다음에 더할 것', '이야기를 만들 수 있습니다. 첫 문장·첫 3초를 여러 버전으로 써 보고 반응을 비교해 보세요.'),
('TRK-storytelling-L', 'track_competency', '스토리텔링 — 첫걸음', '좋아하는 콘텐츠의 구성을 "문제 → 전환 → 해결"로 나눠 보는 연습부터 시작하세요.'),
('TRK-platform_channel-H', 'track_competency', '플랫폼·채널 — 강점으로 보여 주기', '플랫폼별 문법과 알고리즘을 이해하는 힘이 강점입니다. 같은 주제를 플랫폼마다 다르게 만든 사례를 보여 주면 좋습니다.'),
('TRK-platform_channel-M', 'track_competency', '플랫폼·채널 — 다음에 더할 것', '주요 플랫폼은 익숙합니다. 업로드 시간·형식·해시태그를 바꿔 가며 직접 실험해 보세요.'),
('TRK-platform_channel-L', 'track_competency', '플랫폼·채널 — 첫걸음', '인스타그램·유튜브·틱톡에서 같은 브랜드가 어떻게 다르게 말하는지 비교해 보세요.'),
('TRK-content_production-H', 'track_competency', '콘텐츠 제작 — 강점으로 보여 주기', '기획부터 제작·업로드까지 직접 해내는 힘이 강점입니다. 대표작 세 개를 기획 의도·성과와 함께 정리해 두세요.'),
('TRK-content_production-M', 'track_competency', '콘텐츠 제작 — 다음에 더할 것', '만들 수 있습니다. 디자인·영상 도구 하나를 더 익히면 표현의 폭이 넓어집니다.'),
('TRK-content_production-L', 'track_competency', '콘텐츠 제작 — 첫걸음', '휴대폰 하나로 짧은 영상이나 카드뉴스 한 편을 끝까지 완성해 보는 것부터 시작하세요.'),
('TRK-community-H', 'track_competency', '커뮤니티 — 강점으로 보여 주기', '팬과 소통하고 참여를 이끄는 힘이 강점입니다. 참여형 이벤트나 댓글 운영으로 반응을 키운 경험을 정리해 두세요.'),
('TRK-community-M', 'track_competency', '커뮤니티 — 다음에 더할 것', '소통할 수 있습니다. 팬이 직접 참여하는 작은 이벤트 하나를 기획해 보세요.'),
('TRK-community-L', 'track_competency', '커뮤니티 — 첫걸음', '좋아하는 브랜드 계정의 댓글 응대를 관찰하고, 나라면 어떻게 답할지 써 보세요.'),
('TRK-content_analytics-H', 'track_competency', '콘텐츠 분석 — 강점으로 보여 주기', '반응 지표를 해석해 다음 기획에 반영하는 힘이 강점입니다. 데이터로 콘텐츠를 개선한 전후 사례는 강력한 증거입니다.'),
('TRK-content_analytics-M', 'track_competency', '콘텐츠 분석 — 다음에 더할 것', '지표를 볼 줄 압니다. 반응이 좋았던 콘텐츠의 공통점을 찾아 다음 기획에 반영해 보세요.'),
('TRK-content_analytics-L', 'track_competency', '콘텐츠 분석 — 첫걸음', '도달·참여율·저장·공유가 각각 무엇을 뜻하는지 정리하는 것부터 시작하세요.'),
('TRK-market_analysis-H', 'track_competency', '시장 분석 — 강점으로 보여 주기', '시장과 경쟁을 구조적으로 읽는 힘이 강점입니다. 산업 분석 리포트 한 편을 직접 써서 포트폴리오에 넣어 두세요.'),
('TRK-market_analysis-M', 'track_competency', '시장 분석 — 다음에 더할 것', '분석의 틀은 압니다. 공시·산업 리포트에서 숫자를 찾아 근거로 쓰는 연습을 더해 보세요.'),
('TRK-market_analysis-L', 'track_competency', '시장 분석 — 첫걸음', '관심 시장 하나를 골라 3C(고객·경쟁·자사)로 한 장 정리해 보는 것부터 시작하세요.'),
('TRK-stp-H', 'track_competency', 'STP — 강점으로 보여 주기', '고객을 나누고 타깃과 포지셔닝을 정하는 힘이 뚜렷합니다. 세분화 기준과 선택 근거를 담은 기획서가 좋은 증거가 됩니다.'),
('TRK-stp-M', 'track_competency', 'STP — 다음에 더할 것', 'STP의 개념은 이해합니다. 실제 제품 하나로 세분화 기준을 바꿔 가며 타깃을 다시 골라 보세요.'),
('TRK-stp-L', 'track_competency', 'STP — 첫걸음', '좋아하는 제품의 "주 타깃은 누구인가"를 구체적인 한 사람(페르소나)으로 그려 보는 것부터 시작하세요.'),
('TRK-marketing_mix-H', 'track_competency', '마케팅 믹스 — 강점으로 보여 주기', '제품·가격·유통·프로모션을 하나로 묶는 시야가 강점입니다. 신제품 출시 계획서 한 편으로 이 힘을 보여 줄 수 있습니다.'),
('TRK-marketing_mix-M', 'track_competency', '마케팅 믹스 — 다음에 더할 것', '각 요소를 압니다. 가격 정책이 브랜드와 매출에 주는 영향을 사례로 정리해 보세요.'),
('TRK-marketing_mix-L', 'track_competency', '마케팅 믹스 — 첫걸음', '최근 출시된 제품 하나의 4P를 표로 정리해 보는 것부터 시작하세요.'),
('TRK-campaign_planning-H', 'track_competency', '캠페인 기획 — 강점으로 보여 주기', '목표부터 일정까지 기획서로 만드는 힘이 강점입니다. 직접 쓴 기획서와 실행 결과를 함께 정리해 두세요.'),
('TRK-campaign_planning-M', 'track_competency', '캠페인 기획 — 다음에 더할 것', '기획서를 쓸 수 있습니다. 대행사에 보낼 브리프를 한 장으로 쓰는 연습이 명확함을 키웁니다.'),
('TRK-campaign_planning-L', 'track_competency', '캠페인 기획 — 첫걸음', '수상 캠페인 하나를 골라 목표·타깃·메시지·채널·일정으로 역분석해 보세요.'),
('TRK-budget_kpi-H', 'track_competency', '예산·KPI — 강점으로 보여 주기', '목표 지표와 예산을 정하고 성과를 계산하는 힘이 강점입니다. ROI를 계산한 사례는 전략 직무에서 큰 신뢰를 줍니다.'),
('TRK-budget_kpi-M', 'track_competency', '예산·KPI — 다음에 더할 것', '지표를 정할 수 있습니다. 예산을 단계별로 배분하고 근거를 쓰는 연습을 더해 보세요.'),
('TRK-budget_kpi-L', 'track_competency', '예산·KPI — 첫걸음', 'ROI와 KPI의 뜻을 정리하고, 가상의 예산 100만 원을 채널별로 나눠 보는 것부터 시작하세요.'),
('TRK-cross_function-H', 'track_competency', '부서 간 협업 — 강점으로 보여 주기', '여러 부서·파트너와 목표를 맞춰 실행하는 힘이 강점입니다. 이해관계를 조율해 결과를 낸 경험을 정리해 두세요.'),
('TRK-cross_function-M', 'track_competency', '부서 간 협업 — 다음에 더할 것', '함께 일할 수 있습니다. 다른 역할(디자인·개발·영업)의 관점에서 내 기획을 다시 읽어 보세요.'),
('TRK-cross_function-L', 'track_competency', '부서 간 협업 — 첫걸음', '팀 과제에서 역할과 일정을 정리하는 역할을 맡아 보는 것부터 시작하세요.'),
('TRK-funnel_design-H', 'track_competency', '퍼널 설계 — 강점으로 보여 주기', '고객 단계별 이탈 지점을 찾아 개선하는 힘이 강점입니다. 퍼널을 분석해 전환을 올린 사례를 숫자로 정리해 두세요.'),
('TRK-funnel_design-M', 'track_competency', '퍼널 설계 — 다음에 더할 것', '퍼널의 개념을 압니다. 랜딩 페이지 하나를 골라 이탈이 생길 지점을 직접 표시해 보세요.'),
('TRK-funnel_design-L', 'track_competency', '퍼널 설계 — 첫걸음', '노출 → 클릭 → 방문 → 구매 단계를 한 서비스로 그려 보는 것부터 시작하세요.'),
('TRK-ad_platform-H', 'track_competency', '광고 플랫폼 운영 — 강점으로 보여 주기', '광고 계정을 세팅하고 타깃팅·입찰을 다루는 힘이 강점입니다. 운영한 캠페인 구조와 성과를 정리해 두면 실무 투입 근거가 됩니다.'),
('TRK-ad_platform-M', 'track_competency', '광고 플랫폼 운영 — 다음에 더할 것', '플랫폼을 다뤄 봤습니다. 소액으로 직접 캠페인을 운영하며 타깃팅을 바꿔 실험해 보세요.'),
('TRK-ad_platform-L', 'track_competency', '광고 플랫폼 운영 — 첫걸음', '메타·구글 광고의 무료 학습 과정 하나를 수료하는 것부터 시작하세요.'),
('TRK-data_tracking-H', 'track_competency', '데이터 추적 — 강점으로 보여 주기', '분석 도구로 유입과 전환을 측정하는 힘이 강점입니다. GA4 대시보드나 추적 설계 자료를 포트폴리오에 넣어 두세요.'),
('TRK-data_tracking-M', 'track_competency', '데이터 추적 — 다음에 더할 것', '도구를 써 봤습니다. UTM과 전환 이벤트를 직접 설정해 보는 연습을 더해 보세요.'),
('TRK-data_tracking-L', 'track_competency', '데이터 추적 — 첫걸음', 'GA4 데모 계정에 들어가 유입 경로 보고서를 읽어 보는 것부터 시작하세요.'),
('TRK-experiment-H', 'track_competency', '실험·테스트 — 강점으로 보여 주기', '가설을 세우고 테스트로 검증하는 힘이 강점입니다. 가설 → 실험 → 결과 → 다음 행동으로 정리한 사례가 좋은 증거입니다.'),
('TRK-experiment-M', 'track_competency', '실험·테스트 — 다음에 더할 것', '테스트를 해 봤습니다. 한 번에 한 변수만 바꾸고 결과를 기록하는 습관을 더해 보세요.'),
('TRK-experiment-L', 'track_competency', '실험·테스트 — 첫걸음', '같은 메시지로 제목 두 개를 만들어 친구들의 반응을 비교해 보는 작은 실험부터 시작하세요.'),
('TRK-creative_optimization-H', 'track_competency', '소재 최적화 — 강점으로 보여 주기', '성과 데이터로 광고 소재를 개선하는 힘이 강점입니다. 소재별 성과 비교와 개선 과정을 정리해 두세요.'),
('TRK-creative_optimization-M', 'track_competency', '소재 최적화 — 다음에 더할 것', '소재를 만들고 고칠 수 있습니다. 같은 메시지를 이미지·영상·문구로 변형해 성과를 비교해 보세요.'),
('TRK-creative_optimization-L', 'track_competency', '소재 최적화 — 첫걸음', '광고 라이브러리에서 한 브랜드의 소재 열 개를 모아 공통점을 찾아보는 것부터 시작하세요.'),
('TRK-roas_budget-H', 'track_competency', 'ROAS·예산 — 강점으로 보여 주기', '광고 지표를 계산하고 예산을 옮기는 힘이 강점입니다. 예산 재배분으로 ROAS를 개선한 사례는 면접에서 가장 강한 근거입니다.'),
('TRK-roas_budget-M', 'track_competency', 'ROAS·예산 — 다음에 더할 것', '지표를 계산할 수 있습니다. 주간 보고서를 직접 써 보며 의사결정으로 이어지게 정리해 보세요.'),
('TRK-roas_budget-L', 'track_competency', 'ROAS·예산 — 첫걸음', 'CPC·CPA·CTR·CVR·ROAS의 계산식을 정리하고 예제로 한 번씩 계산해 보는 것부터 시작하세요.')
